import json
W='sıfır bir iki üç dört beş altı yedi sekiz dokuz'.split()
def sp(d):
    return ' '.join(W[int(c)] for c in str(d or '') if c.isdigit())
def tr(s):
    s=str(s or '').replace('İ','i').replace('I','ı').lower()
    for a,b in zip('ışğüöç','isguoc'):
        s=s.replace(a,b)
    return ' '.join(s.split())
def nm(c):
    n=str(c.get('productName') or '').strip()
    return n if 0<len(n)<=30 else ''
def dm(num,d):
    t=str(num or '')[-len(d):]
    return len(t)==len(d) and all(x=='*' or x==y for x,y in zip(t,d))
def ask(cs):
    ex=[]
    for c in cs:
        if nm(c) and nm(c) not in ex:
            ex.append(nm(c))
    q='Hangi kartınızın borcunu öğrenmek istersiniz?'
    if ex:
        q=q+' Örneğin, '+' veya '.join(ex[:2])+' diyebilirsiniz.'
    return 'Ask exactly: “'+q+'”'
RESET=['b_rc','b_date','b_due','b_next_date','b_next_due','b_status','b_auto','tl_auto']+[c+'_'+f for c in ('tl','usd','eur','gbp') for f in ('sd','mp','rd','rmp','td')]
try:
    cards=vars.get('cards')
    if isinstance(cards,str):
        cards=json.loads(cards)
    if not isinstance(cards,list):
        cards=[]
        for i in range(20):
            p='cards_list_response.data.data.cards.'+str(i)+'.'
            if not vars.get(p+'cardNumber'):
                break
            cards.append(dict(cardNumber=vars.get(p+'cardNumber'),cardNumberLast4=vars.get(p+'cardNumberLast4'),productName=vars.get(p+'productName'),isMainCard=vars.get(p+'isMainCard')))
    cards=[c for c in cards if isinstance(c,dict) and c.get('cardNumber')]
    elig=[c for c in cards if str(c.get('isMainCard')).lower()!='false']
    read=[x for x in str(vars.get('read_cards') or '').split(',') if x]
    left=[c for c in elig if c.get('cardNumber') not in read]
    vars['card_list_text']='; '.join((nm(c) or 'adı olmayan kart')+' (son dört hane: '+sp(c.get('cardNumberLast4'))+')' for c in elig)
    name=str(vars.get('card_name_said') or '').strip()
    if tr(name) in ('none','null'):
        name=''
    dig=''.join(x for x in str(vars.get('card_digits_said') or '') if x.isdigit())
    status='ask'
    hint=ask(left or elig)
    pick=None
    clear=False
    if not elig:
        status='none'
    elif len(cards)==1:
        pick=elig[0]
    elif name or dig:
        cand=list(cards)
        if name:
            n=tr(name)
            same=[c for c in cand if tr(c.get('productName'))==n]
            cand=same or [c for c in cand if tr(c.get('productName')) and (n in tr(c.get('productName')) or tr(c.get('productName')) in n)]
        if dig:
            cand=[c for c in cand if dm(c.get('cardNumber'),dig)]
        if len(cand)==1 and cand[0] in elig:
            pick=cand[0]
        elif len(cand)==1:
            clear=True
            hint='Say that this card cannot be used for a statement debt query here and ask the caller to choose another card. '+ask(left or elig)
        elif not cand:
            clear=True
            hint='Say “Bu bilgiyle eşleşen bir kartınız bulunmuyor.”, read the names of the eligible cards from the list again, then ask which one. This used one try.'
        elif len(dig)==4:
            hint='Ask exactly: “Son dört hanesi '+sp(dig)+' olan birden fazla kartınız var. Kartınızın son altı hanesini söyler misiniz?”'
        elif len(dig)>4:
            hint='Ask exactly: “Son altı hanesi aynı olan birden fazla kartınız var. Kart numaranızı söyler misiniz?”'
        elif len(set(tr(c.get('productName')) for c in cand))==1:
            hint='Ask exactly: “'+(nm(cand[0]) or 'Bu')+' isimli birden fazla kartınız var. Kartınızın son dört hanesini söyler misiniz?”'
        else:
            hint='Read only these matching cards and ask which one: '+', '.join(nm(c) or ('sonu '+sp(c.get('cardNumberLast4'))+' ile biten kart') for c in cand)
    if pick:
        status='unique'
        clear=True
        read=[x for x in read if x!=pick.get('cardNumber')]+[pick.get('cardNumber')]
        vars['read_cards']=','.join(read)
        rest=[c for c in elig if c.get('cardNumber') not in read]
        vars['other_cards_left']='yes' if rest else 'no'
        vars['selected_card_number']=pick.get('cardNumber')
        vars['card_last4']=str(pick.get('cardNumberLast4') or str(pick.get('cardNumber'))[-4:])
        vars['card_name']=nm(pick)
        hint=ask(rest or elig)
        for k in RESET:
            vars[k]=''
    if clear:
        vars['card_name_said']='none'
        vars['card_digits_said']='none'
    vars['match_hint']=hint
    vars['match_status']=status
except Exception:
    vars['match_status']='error'

select_card.task_message:
Your only job here is to find out which of the caller's own cards they want the statement debt for. Do not call any tool in this step except the transition_to_exit tools.
The caller's eligible cards (name and last four digits): {{card_list_text}}
What to say now: {{match_hint}}
Rules: give at most two example names and only names from the list above; never name a card the caller does not have. The debt is read for one card at a time: if the caller asks for all or several cards, say “Borç bilgisini kartlarınız için tek tek okuyabiliyorum.” and ask the selection question again with the examples; this uses one try and is never a reason to end the call. If the caller cannot give digits (for example the card is not with them), ask for the card name instead. Never repeat digits or a card number the caller says and never say a 'continuing with your card' sentence or ask 'is that right?': the debt reading starts by itself once the card is identified. Three tries per question.

