import datetime
W='sıfır bir iki üç dört beş altı yedi sekiz dokuz'.split()
M='Ocak Şubat Mart Nisan Mayıs Haziran Temmuz Ağustos Eylül Ekim Kasım Aralık'.split()
N=dict(tl='Türk Lirası',usd='Dolar',eur='Euro',gbp='İngiliz Sterlini')
SUB=dict(tl='kuruş',usd='sent',eur='sent',gbp='peni')
SUF=dict(Lirası='’dır',Dolar='’dır',Euro='’dur',Sterlini='’dir',kuruş='’tur',sent='’tir',peni='’dir')
D1=['','’dir','’dir','’tür','’tür','’tir','’dır','’dir','’dir','’dur']
D10=['','’dur','’dir','’dur','’tır','’dir','’tır','’tir','’dir','’dır']
def s(k):
    v=vars.get(k)
    return '' if v is None or str(v).strip() in ('None','null') else str(v).strip()
def g(k):
    try:
        return float(s(k))
    except Exception:
        return None
def sp(d):
    return ' '.join(W[int(c)] for c in d if c.isdigit())
def dt(x):
    try:
        return datetime.date(int(x[6:10]),int(x[3:5]),int(x[0:2]))
    except Exception:
        return None
def sd(d):
    return str(d.day)+' '+M[d.month-1]+' '+str(d.year)
def ysuf(y):
    if y%10:
        return D1[y%10]
    if (y//10)%10:
        return D10[(y//10)%10]
    return '’dür' if (y//100)%10 else '’dir'
def amt(c,x):
    k=int(round(abs(x)*100))
    a='{:,}'.format(k//100).replace(',','.')+' '+N[c]
    return a+(' '+str(k%100)+' '+SUB[c] if k%100 else '')
def cop(t):
    return t+SUF.get(t.split()[-1],'’dir')
def lst(cs):
    n=[N[c] for c in cs]
    return n[0] if len(n)==1 else ', '.join(n[:-1])+' ve '+n[-1]
try:
    nw=s('now')
    today=datetime.date(int(nw[0:4]),int(nw[5:7]),int(nw[8:10]))
    name=s('card_name')
    intro='Sonu '+sp(s('card_last4'))+' ile biten '+(name+' ' if name else '')+'kartınız'
    cur=['tl','usd','eur','gbp']
    pres=[c for c in cur if g(c+'_sd') is not None or g(c+'_rd') is not None]
    owe=[c for c in pres if (g(c+'_rd') or 0)>0]
    clr=[c for c in pres if c not in owe]
    sdt=dt(s('b_date'))
    due=dt(s('b_due'))
    ndt=dt(s('b_next_date'))
    ndue=dt(s('b_next_due'))
    tot=[c for c in pres if (g(c+'_td') or 0)>0]
    tots=' '.join(N[c]+' cinsinden toplam borcunuz '+cop(amt(c,g(c+'_td')))+'.' for c in tot) or 'Toplam borcunuz bulunmamaktadır.'
    kind='debt'
    if not sdt:
        kind='no_statement'
        text='Kartınızın henüz kesilmiş bir ekstresi olmadığı için ekstre borcunuz bulunmamaktadır.'+(' İlk hesap kesim tarihiniz '+sd(ndt)+' olacak.' if ndt else '')
    elif sdt==today or ndt==today:
        text='Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek. '+intro+' için '+tots
    elif s('b_status')=='NO_DEBT' or not owe:
        kind='no_debt'
        tl=g('tl_td') or 0
        text=intro+'ın '+sd(sdt)+' tarihli ekstresinden borcunuz bulunmamaktadır. '+('Gelecek dönemler dahil toplam borcunuz '+cop(amt('tl',tl))+'.' if tl>0 else 'Gelecek dönemler dahil bir borcunuz bulunmamaktadır.')+(' Son ödeme tarihiniz '+sd(ndue)+' olacaktır.' if ndue and tl>0 else '')
    elif due and due<today:
        text=intro+' için son ödeme tarihi olan '+sd(due)+' geçti. '+tots
        if s('b_auto')=='Y' and (g('tl_auto') or 0)>0:
            text=text+' Otomatik ödeme talimatınızdan alınacak kalan tutar '+cop(amt('tl',g('tl_auto')))+'.'
    else:
        parts=[]
        for c in owe:
            sv=g(c+'_sd') or 0
            mp=g(c+'_mp') or 0
            rd=g(c+'_rd') or 0
            rm=g(c+'_rmp') or 0
            if c!='tl':
                t=N[c]+' borcunuz '+amt(c,sv)+', kalan toplam borcunuz '+amt(c,rd)+', ödenmesi gereken minimum tutar '+cop(amt(c,mp))+'.'
            elif rm>0 and rm>=mp:
                t='Türk Lirası borcunuz '+amt(c,sv)+', ödenmesi gereken minimum tutar '+cop(amt(c,mp))+'.'
            elif rm<=0:
                t='Türk Lirası borcunuz '+amt(c,sv)+', kalan toplam borcunuz '+cop(amt(c,rd))+'. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
            else:
                t='Türk Lirası borcunuz '+amt(c,sv)+', ödenmesi gereken minimum tutar '+amt(c,mp)+', kalan toplam borcunuz '+amt(c,rd)+', kalan minimum ödeme tutarınız '+cop(amt(c,rm))+'.'
            if not parts:
                t=intro+'a ait '+sd(sdt)+' tarihinde kesilen ekstre '+t
            parts.append(t)
        if clr:
            parts.append(lst(clr)+' borcunuz bulunmamaktadır.')
        if due==today:
            parts.append('Borçlarınız için son ödeme tarihiniz bugündür.')
        elif due:
            parts.append('Borçlarınız için son ödeme tarihiniz '+sd(due)+ysuf(due.year)+'.')
        text=' '.join(parts)
    em=s('reg_email')
    rc=s('email_rc')
    ct=s('comm_type').lower()
    if not sdt:
        es='no_statement'
    elif rc=='1':
        es='registered' if em and ct!='phone' else 'none'
    else:
        es='error'
    loc=em.split('@')[0]
    if len(loc)<=20 and loc.replace('.','').isalpha():
        q='Ekstrenizi '+em+' adresine göndermemi ister misiniz?'
    else:
        q='Ekstrenizi '+loc[:1]+' ile başlayan kayıtlı e-posta adresinize göndermemi ister misiniz?'
    offer='Hesap kesim tarihinizi değiştirebilirim ya da ekstrenizi kayıtlı mail adresinize gönderebilirim.' if es in ('registered','error') else 'Hesap kesim tarihinizi değiştirebilirim.'
    oq='Başka bir kartınızın borcunu öğrenmek ister misiniz?'
    more=s('other_cards_left')=='yes'
    if kind in ('no_statement','no_debt'):
        after=('Then, in the same turn, ask exactly: “'+oq+'” If the caller says no, call transition_to_exit_main_menu.') if more else 'Then say nothing more and call transition_to_exit_main_menu in the same turn.'
    else:
        after=('Then, in the same turn, ask exactly: “'+oq+'” When the caller says no, say exactly: “'+offer+'”') if more else ('Then, in the same turn, say exactly: “'+offer+'”')
    vars['debt_text']=text
    vars['after_text']=after
    vars['reading_kind']=kind
    vars['email_state']=es
    vars['email_question']=q
    vars['pdf_statement_date']=s('b_date')
    vars['next_action']='none'
    vars['send_confirm']='none'
    vars['format_status']='ok'
except Exception:
    vars['format_status']='error'

